```js
import assert from "node:assert/strict";
const text = "redo the prereq, then reread";
assert.deepEqual(text.match(/\bre\w*/g), ["redo", "reread"]);
assert.deepEqual(text.match(/re\w*/g), ["redo", "rereq", "reread"]); // without \b, the middle of prereq leaks in
console.log(text.match(/\bre\w*/g));
